final class Vault private (           // constructor private: only the companion builds it
    private val store: Store,
    private val policy: Policy,
) {
  def read(who: Subject, id: Id): Record = {
    if (!policy.allows(who, id)) throw AccessDenied(id)  // check precedes the access
    store.load(id)                                       // store never leaves the class
  }
}
object Vault {                        // companion: the trusted owner / factory
  def open(store: Store, policy: Policy): Vault = new Vault(store, policy)
}
